from lib import *
S = SS('j271')
steps = [
    step("不调用 initialize、直接 generateKeyPair() 得到的默认参数随 JDK 版本变化:RSA 在 JDK 17 是 2048 位(公钥编码 294 字节、私钥 1217 字节),在 JDK 21 与 27 是 3072 位(422 / 1794 字节);EC 在 JDK 17 是 256 位曲线(公钥 91 字节),在 JDK 21 与 27 是 384 位(120 字节);DH 从 2048 位变成 3072 位素数;DSA 一直是 2048 位;Ed25519 与 X25519 不变(44 / 48 字节);RSASSA-PSS 与 RSA 同步变化。依赖默认值的代码在升级 JDK 之后密钥大小会悄悄改变。", t=tl(S(1)), done=lidx(S(1), '[JDK 17]', 'RSA         不 initialize 直接 generateKeyPair():2048 位模数'), mark=lidx(S(1), '[JDK 21]', '3072 位模数', '曲线阶 384 位', '[JDK 27]'), b=bars([['JDK 17 RSA 默认', 2048, '2048 位'], ['JDK 21 RSA 默认', 3072, '3072 位'], ['JDK 17 EC 默认', 256, '256 位'], ['JDK 21 EC 默认', 384, '384 位']], 3072, done=[0, 1, 2, 3]), kv=KV([['RSA 默认', 'JDK 17:2048 位 → JDK 21 / 27:3072 位'], ['EC 默认', 'JDK 17:256 位 → JDK 21 / 27:384 位'], ['Ed25519 / X25519', '不变']], ['RSA 默认'])),
    step("RSA(JDK 21):initialize(511) 抛 InvalidParameterException(Invalid key sizes);512、1023、1024、2048、4097 都成功(模数位数与指定值完全一致,包括 1023 与 4097);16384 参数检查通过,16385 抛异常。默认公钥指数 65537;RSAKeyGenParameterSpec 指定 e = 3、17、65537、65539 都成功,e = 2 或 4 抛 “Public exponent must be an odd number”,e = 1 抛 “must be 3 or larger”。私钥是 RSAPrivateCrtKey,p 与 q 各 1024 位,p×q = n,d 2045 位,保存 CRT 参数。生成 200 把 initialize(2048) 的密钥,模数恰好 2048 位的有 200 把。", t=tl(S(2)), done=lidx(S(2), 'RSA initialize(511)', 'RSA initialize(512)', 'RSA initialize(1023)'), mark=lidx(S(2), 'RSA initialize(16385)', '默认公钥指数', 'e = 2', 'RSAPrivateCrtKey', '模数恰好 2048 位'), kv=KV([['密钥长度', '512 到 16384 位(1023 与 4097 也可以),511 与 16385 拒绝'], ['公钥指数', '默认 65537;3、17、65539 可用;偶数与 1 拒绝'], ['模数', '200 把 2048 位的密钥都恰好 2048 位']], ['密钥长度'])),
    step("EC(JDK 21):initialize(256) 得到 secp256r1,384 得到 secp384r1,521 得到 secp521r1;192 与 224 抛 ProviderException: Curve not supported(P-192、P-224 不可用);255 与 522 抛 InvalidParameterException: No EC parameters available for key size。按名字初始化:secp256r1 / secp384r1 / secp521r1 成功,“NIST P-256”“X9.62 prime256v1”“1.2.840.10045.3.1.7” 都成功,但 “prime256v1”(OpenSSL 的名字)抛 Unknown curve name,secp256k1、secp224r1、brainpoolP256r1 抛 Curve not supported。所有提供者里注册的 KeyPairGenerator 算法只有 11 个:DSA、DiffieHellman、EC、Ed25519、Ed448、EdDSA、RSA、RSASSA-PSS、X25519、X448、XDH。", t=tl(S(3)), done=lidx(S(3), 'EC initialize(192)', 'EC initialize(224)', 'EC initialize(256)'), mark=lidx(S(3), 'EC initialize(522)', 'secp256k1', 'prime256v1', 'NIST P-256', '所有提供者里注册'), kv=KV([['可用曲线', 'secp256r1 / secp384r1 / secp521r1'], ['不可用', 'P-192、P-224、secp256k1、brainpool 抛 Curve not supported'], ['名字', '“prime256v1” 不认识,“NIST P-256” 与 OID 认识']], ['不可用'])),
    step("生成耗时(JDK 21,最快 / 中位数 / 最慢):RSA 2048 30 次 28.5 / 65.2 / 294.1 ms(最慢是中位数的 4.5 倍);RSA 3072 30 次 99.3 / 275.2 / 786.7 ms;RSA 4096 12 次 725 / 1227 / 2275 ms;EC 256 0.12 / 0.14 / 0.25 ms,384 0.66 / 0.73 / 1.58 ms,521 1.17 / 1.48 / 2.19 ms;Ed25519 0.22 / 0.27 / 0.80 ms;X25519 0.11 / 0.18 / 0.29 ms;DH 2048 与 DSA 2048(使用预置参数)约 0.34 ms。RSA 要搜索素数,耗时波动大(几倍),EC 与 Edwards 曲线几乎固定。", t=tl(S(4)), done=lidx(S(4), 'RSA      2048  30 次', 'RSA      3072', 'RSA      4096'), mark=lidx(S(4), 'EC       256', 'EC       521', 'Ed25519', 'DH       2048'), b=bars([['RSA 2048 中位数', 65.21, '65.2 ms'], ['RSA 3072 中位数', 275.19, '275.2 ms'], ['RSA 4096 中位数', 1226.56, '1227 ms'], ['EC 256 中位数', 0.14, '0.14 ms'], ['Ed25519 中位数', 0.27, '0.27 ms']], 1230, done=[0, 1, 2, 3, 4]), kv=KV([['RSA 2048', '最快 28.5 / 中位数 65.2 / 最慢 294.1 ms'], ['EC P-256', '0.12 / 0.14 / 0.25 ms']], ['RSA 2048'])),
    step("固定种子的 SecureRandom:用 setSeed(12345) 的 SHA1PRNG 各生成一把 RSA 1024 密钥,两次的模数完全相同(88e453ac…),EC P-256 的私钥相同;DRBG 与 NativePRNG 两次的模数不同(setSeed 只是补充熵)。默认 new SecureRandom() 是 NativePRNG(SUN 提供者)。SHA1PRNG 先 setSeed(42) 再取字节得到 d50ac288…,先取字节再 setSeed(42) 得到 986aadeb…——第一次取字节之后 setSeed 只是追加熵,不再让输出可重现。测试里想要可重现的密钥可以用 SHA1PRNG,但这样生成的密钥永远不能用于生产。", t=tl(S(5)), done=lidx(S(5), 'SHA1PRNG:用 setSeed(12345)', 'DRBG:用 setSeed(12345)'), mark=lidx(S(5), 'NativePRNG:用 setSeed', 'SHA1PRNG + setSeed(1)', '默认 new SecureRandom()', 'SHA1PRNG:先 setSeed(42)'), kv=KV([['SHA1PRNG + setSeed', '两次生成的 RSA 模数 / EC 私钥完全相同'], ['DRBG / NativePRNG + setSeed', '不同,不可重现']], ['SHA1PRNG + setSeed'])),
    step("编码与互通:RSA、EC、Ed25519 的私钥 getFormat() 都是 PKCS#8,公钥都是 X.509(私钥 1217 / 67 / 48 字节)。OpenSSL(4.0.3)用 pkey 直接读取 DER:RSA 私钥 “Private-Key: (2048 bit, 2 primes)”、公钥 “Public-Key: (2048 bit)”;EC 私钥 “(256 bit field, 128 bit security level)”;Ed25519 “ED25519 Private-Key”。Java 的 KeyPairGenerator 输出不需要转换就能被 OpenSSL 解析。", t=tl(S(6)), done=lidx(S(6), 'RSA:私钥 getFormat()', 'EC:私钥 getFormat()'), mark=lidx(S(6), 'Ed25519:私钥 getFormat()', 'openssl pkey 读取 RSA', 'openssl pkey 读取 EC', 'openssl pkey 读取 Ed25519'), kv=KV([['私钥格式', 'PKCS#8(RSA 1217 / EC 67 / Ed25519 48 字节)'], ['公钥格式', 'X.509'], ['OpenSSL', 'pkey -inform DER 直接读取']], ['OpenSSL'])),
]
A = mkartj('j271', 271, 'Java,密码学,KeyPairGenerator,RSA,EC,SecureRandom,密钥生成,真实验证,动画演示',
    '在 JDK 17 / 21 / 27 上实测 KeyPairGenerator:不 initialize 时 RSA 默认从 2048 位升到 3072 位、EC 从 256 升到 384;RSA 512–16384 位都可生成(1023 与 4097 也可以)、公钥指数必须是奇数;EC 只支持 P-256 / 384 / 521;RSA 2048 生成耗时 28–294 ms 波动 4.5 倍而 EC 几乎固定;SHA1PRNG + setSeed 可重现密钥;输出可被 OpenSSL 直接读取。',
    '生成密钥对只有两行代码,但默认值、边界和耗时都有细节。这篇用多个 JDK 版本和 OpenSSL 量出:默认参数怎么随版本变化,RSA 与 EC 能接受什么参数,生成耗时的波动,以及固定种子能不能重现密钥。',
    [('2048 → 3072', 'RSA 不 initialize 时的默认模数位数:JDK 17 与 JDK 21 / 27'), ('28.5–294.1 ms', 'RSA 2048 生成 30 次的最快与最慢(中位数 65.2 ms);EC P-256 为 0.12–0.25 ms'), ('相同 vs 不同', '用 setSeed(12345) 的 SHA1PRNG 与 DRBG 各生成两把 RSA 1024 密钥,模数是否相同')],
    [('默认参数', None), ('RSA 的边界', None), ('EC 的曲线', None), ('生成耗时', None), ('固定种子', None), ('编码与 OpenSSL', None)],
    steps, [ENV_J + '。JDK 17.0.20(默认值)、21.0.12(其余)、27(默认值);OpenSSL 4.0.3;耗时是自写的 nanoTime 循环,次数见各行', '没有验证:Windows 与 Linux 上 NativePRNG 的差异、PKCS#11 与 HSM 提供者、BouncyCastle 的 KeyPairGenerator、RSA 超过 8192 位的实际生成、FIPS 模式、JDK 22–26 的默认值变化的具体版本'], 'KeyPairGenerator')
